import type { WebsiteMethodPolicy } from "./authority.js";
/**
 * Shared RPC types for panel/worker communication.
 *
 * This package is the single source of truth for the message protocol and
 * the unified RPC client API (createRpcClient).
 */

import type { DecodedFramedStream } from "./protocol/streamCodec.js";
export type { DecodedFramedStream };

/**
 * Coordinate of the upstream trajectory invocation selected by the trusted
 * calling vessel as the cause of an RPC call.
 *
 * This is provenance, not identity or authority. The receiving host accepts it
 * only when the authenticated caller is bound to the named trajectory; the
 * semantic command later verifies that the invocation exists at that head.
 * The coordinate is exact once selected, but selecting the invocation that
 * actually spawned the call remains the vessel's responsibility.
 */
export interface RpcCausalParent {
  kind: "trajectory-invocation";
  logId: string;
  head: string;
  invocationId: string;
}

/**
 * RPC request message sent between endpoints.
 */
export interface RpcRequest {
  type: "request";
  requestId: string;
  fromId: string;
  method: string;
  args: unknown[];
  /**
   * Set only by extension callers, echoing the host-issued request identity
   * from the inbound extension invocation frame. It is an exact call edge,
   * not an authorization credential or a second invocation identity.
   */
  parentRequestId?: string;
  /** Exact non-authorizing provenance edge for a tool-caused call. */
  causalParent?: RpcCausalParent;
}

/**
 * RPC response message (success case).
 */
export interface RpcResponseSuccess {
  type: "response";
  requestId: string;
  result: unknown;
}

/** Stable error category for caller control flow across every RPC transport. */
export type RpcErrorKind =
  | "access"
  | "service"
  | "transport"
  | "protocol"
  | "application"
  | "internal";

/**
 * Schema-owned application failure payload carried unchanged through RPC.
 *
 * The transport deliberately does not interpret this value. Services own its
 * schema (for example, `vcsErrorSchema`), while every relay preserves it as a
 * single error channel alongside the human-readable diagnostic.
 */
export type RpcErrorData = unknown;

/**
 * RPC response message (error case).
 */
export interface RpcResponseError {
  type: "response";
  requestId: string;
  error: string;
  errorKind: RpcErrorKind;
  /** Original error code (e.g. "ENOENT", "EACCES") preserved across the RPC boundary */
  errorCode?: string;
  /** Structured service-domain failure data; callers must not parse `error`. */
  errorData?: RpcErrorData;
  diagnosticId?: string;
  /** Original stack, when available. Intended for diagnostics, not control flow. */
  errorStack?: string;
}

/**
 * Union type for RPC responses.
 */
export type RpcResponse = RpcResponseSuccess | RpcResponseError;

/**
 * RPC event message for one-way notifications.
 */
export interface RpcEvent {
  type: "event";
  fromId: string;
  event: string;
  payload: unknown;
}

/**
 * Streaming RPC request. Initiates a long-lived call whose response
 * body is delivered as a sequence of `RpcStreamFrameMessage` frames
 * (HEAD → DATA* → END | ERROR), tagged by `requestId`. The bridge
 * assembles those frames into a `ReadableStream<Uint8Array>` body for
 * the `Response` returned by `stream`.
 */
export interface RpcStreamRequest {
  type: "stream-request";
  requestId: string;
  fromId: string;
  method: string;
  args: unknown[];
  /** See `RpcRequest.parentRequestId`. */
  parentRequestId?: string;
  /** Exact upstream tool invocation; provenance only, never authorization. */
  causalParent?: RpcCausalParent;
}

/**
 * One frame of a streaming RPC response. `frameType` is one of the
 * codes from `@vibestudio/credential-client/streamFraming`
 * (0x01 HEAD, 0x02 DATA, 0x03 END, 0x04 ERROR). DATA payloads are
 * base64-encoded so binary content survives JSON-over-WS / IPC
 * transport. HEAD/END/ERROR payloads are JSON strings.
 *
 * Many transports (Electron IPC, WebSocket) JSON-serialize messages,
 * so DATA frames can't carry raw bytes; base64 is the lowest-common-
 * denominator encoding. The HTTP `/rpc/stream` endpoint uses the same
 * frame codec but on a binary stream (no base64 there).
 */
export interface RpcStreamFrameMessage {
  type: "stream-frame";
  requestId: string;
  fromId: string;
  frameType: number;
  payload: string;
}

/**
 * Cancel an in-flight streaming RPC. Sent by the caller side when
 * the consumer of the streaming response cancels (e.g. by
 * `response.body.cancel()` or via an `AbortSignal`). The server side
 * uses this to abort the upstream fetch so it stops pulling bytes
 * from a corpse.
 */
export interface RpcStreamCancel {
  type: "stream-cancel";
  requestId: string;
  fromId: string;
}

/**
 * Cancel an in-flight unary RPC. This is a transport-level ownership signal:
 * once the caller abandons the request, the callee's `RpcRequestContext.signal`
 * is aborted so nested work can release cooperatively. The request id is
 * scoped by the authenticated caller/connection at trust boundaries.
 */
export interface RpcRequestCancel {
  type: "request-cancel";
  requestId: string;
  fromId: string;
}

/**
 * Union type for all RPC messages.
 */
/** A complete receiver-owned declaration, scoped to its authenticated live transport. */
export interface RpcExposure {
  type: "exposure";
  entries: Array<{
    name: string;
    kind: "method" | "stream" | "event";
    website: WebsiteMethodPolicy;
  }>;
}

export type RpcMessage =
  | RpcExposure
  | RpcRequest
  | RpcResponse
  | RpcEvent
  | RpcStreamRequest
  | RpcStreamFrameMessage
  | RpcStreamCancel
  | RpcRequestCancel;

export type ExposedMethods = Record<string, (...args: unknown[]) => unknown | Promise<unknown>>;

/**
 * Event listener callback type.
 */
export type RpcEventListener = (fromId: string, payload: unknown) => void;

/**
 * Transport abstraction for sending and receiving RPC messages.
 */
export interface RpcTransport {
  /**
   * Send a message to a target endpoint.
   */
  send(targetId: string, message: RpcMessage): Promise<void>;

  /**
   * Register a handler for incoming messages from a specific source.
   * Returns an unsubscribe function.
   */
  onMessage(sourceId: string, handler: (message: RpcMessage) => void): () => void;

  /**
   * Register a handler for messages from any source.
   *
   * `callerKind` is the gateway-verified kind of the source when the transport
   * can supply it (optional/additive — paths that don't stamp it omit it, and
   * the bridge surfaces `"unknown"`). Pairs with the trusted `sourceId`.
   * Returns an unsubscribe function.
   */
  onAnyMessage(
    handler: (sourceId: string, message: RpcMessage, callerKind?: CallerKind) => void
  ): () => void;
}

/**
 * The authenticated identity of an INBOUND caller — i.e. "who called me".
 *
 * This is the single, canonical inbound-caller shape across every layer:
 * - the unified client passes it to `expose` handlers;
 * - `DurableObjectBase.caller` returns it (sourced from signed headers);
 * - the server's `VerifiedCaller.caller` exposes it (a thin view over its
 *   richer capability/code identity).
 *
 * `callerId`/`callerKind` are gateway-verified (the principal the server
 * authenticated and stamped onto routed messages), NOT the self-reported
 * `RpcRequest.fromId`. `callerKind` is `"unknown"` on delivery paths where the
 * kind isn't carried (local dispatch, or transports that don't stamp it);
 * authorization code should treat `"unknown"` as least-privileged.
 *
 * Distinct from `RpcCaller`, which is the OUTBOUND interface ("a thing you can
 * make calls through").
 */
export interface AuthenticatedCaller {
  callerId: string;
  callerKind: CallerKind | "unknown";
  /**
   * Stable identity of the workspace that owns this caller. Trust-boundary
   * transports replace caller-supplied values with the workspace verified for
   * the authenticated session. This is attribution, not a principal kind or
   * an authority grant.
   */
  workspaceId?: string;
  /**
   * Stable visible panel slot for panel callers whose runtime `callerId` is a
   * per-navigation entity. Only the trusted server/bridge stamps this field.
   */
  callerPanelId?: string;
  /**
   * Owning user (WP4 §2.4), mirrored from the host-verified
   * `VerifiedCaller.subject.userId` when this caller crosses into userland (DO
   * dispatch, worker, bridge). ATTRIBUTION ONLY — the receiver treats it as
   * provenance metadata for message authorship/presence, NEVER re-validating it
   * as a capability (a userland actor cannot widen a grant by presenting a
   * `userId`; authority still gates on code identity, WP0 §6). Absent for the
   * enumerated pre-identity bootstrap principals and `"unknown"` delivery paths.
   */
  userId?: string;
}

export type CallerKind =
  | "shell"
  | "panel"
  | "app"
  | "worker"
  | "do"
  | "extension"
  | "server"
  // An autonomous external process acting as a workspace agent. Distinct from `shell`
  // (a paired human-driven device) so policy/approval flows can treat
  // autonomous tool use differently. Authenticates with an entity-scoped agent
  // credential (`agent:<agentId>:<token>`) and carries an `agentBinding` on the
  // connection.
  | "agent";

/**
 * Frame yielded by a streaming method handler. Mirrors the wire frame
 * format defined in `@vibestudio/rpc/protocol/streamCodec` but
 * uses runtime types (Uint8Array for DATA, structured objects for
 * HEAD/END/ERROR) — the client serializes them when sending across
 * the wire.
 */
export type StreamingMethodFrame =
  | {
      kind: "head";
      status: number;
      statusText: string;
      headerPairs: Array<[string, string]>;
      finalUrl: string;
    }
  | { kind: "chunk"; bytes: Uint8Array }
  | { kind: "end"; bytesIn: number }
  | {
      kind: "error";
      status: number;
      message: string;
      code?: string;
      errorKind: RpcErrorKind;
      errorData?: RpcErrorData;
      diagnosticId?: string;
    };

export type StreamingMethodHandler = (
  args: unknown[],
  sink: (frame: StreamingMethodFrame) => Promise<void> | void,
  abortSignal: AbortSignal
) => Promise<void>;

/** Transport owner; hub control is not a workspace or a workspace member. */
export type RpcDestination =
  | { readonly kind: "workspace"; readonly workspaceId: string }
  | { readonly kind: "hub" };

export interface RpcTargetOptions {
  /**
   * Route this operation to one exact transport owner. Omission means the caller's
   * current workspace; transports must not search other workspaces by target
   * name. This caller-selected destination is distinct from the authenticated
   * origin at `delivery.caller.workspaceId`.
   */
  destination?: RpcDestination;
}

export interface RpcCallOptions extends RpcTargetOptions {
  timeoutMs?: number;
  signal?: AbortSignal;
  idempotencyKey?: string;
  /** Request read-only containment: the server dispatcher refuses any non-`read`
   *  method for this call. Propagated to `ServiceContext.readOnly`. */
  readOnly?: boolean;
  /**
   * Exact upstream tool invocation. The host verifies its trajectory against
   * the authenticated presenter's binding. It grants no permissions.
   */
  causalParent?: RpcCausalParent;
  /**
   * Override the client's authority-acquisition behavior for this invocation.
   * Durable effect owners use `return` so an EACQUIRE result parks their own
   * journaled outbox row instead of holding a transport request across a human
   * decision.
   */
  authorityAcquisition?: "wait" | "return";
}

export interface RpcStreamOptions extends RpcTargetOptions {
  signal?: AbortSignal;
  idempotencyKey?: string;
  /** Explicit caller deadline for response headers; Iroh has no default deadline. */
  headTimeoutMs?: number;
  /**
   * Maximum silence between response-body frames. `null` explicitly disables
   * the body deadline for intentionally long-lived streams.
   */
  bodyIdleTimeoutMs?: number | null;
  /** Request read-only containment for streaming calls. */
  readOnly?: boolean;
  /** Exact upstream tool invocation; provenance only, never authorization. */
  causalParent?: RpcCausalParent;
  /**
   * Streaming REQUEST body. Body-capable transports carry it on their native
   * streaming wire (Iroh bulk frames or ordered WebSocket upload frames).
   * Other transports throw; bodies never silently fall back to base64-in-args.
   */
  body?: ReadableStream<Uint8Array> | null;
  /**
   * Transport scheduling intent. Interactive is the default for subscriptions
   * and ordinary RPC bodies; immutable artifacts and explicit large transfers
   * opt into bulk. This is QoS only and grants no authority.
   */
  trafficClass?: RpcStreamTrafficClass;
}

export type RpcStreamTrafficClass = "interactive" | "bulk";

export interface RpcCaller {
  call<T = unknown>(
    targetId: string,
    method: string,
    args: unknown[],
    options?: RpcCallOptions
  ): Promise<T>;
  /**
   * Streaming call. Returns a `Response` whose body is a real
   * `ReadableStream<Uint8Array>` — the upstream's response bytes,
   * delivered chunk-by-chunk over whichever transport this caller
   * uses. Transports that can't physically stream wrap a buffered
   * response in a synthetic stream so the API surface is uniform
   * across all bridges (no callers need to duck-type capability).
   *
   * Only `credentials.proxyFetch` is currently routed through this
   * path; other methods continue to use `call` for their JSON
   * request/response shape.
   */
  stream(
    targetId: string,
    method: string,
    args: unknown[],
    options?: RpcStreamOptions
  ): Promise<Response>;
}

export interface RpcEnvelope {
  from: string;
  target: string;
  /** Exact destination owner. Omission keeps routing local to the current transport. */
  destination?: RpcDestination;
  delivery: {
    caller: AuthenticatedCaller;
    idempotencyKey?: string;
    /** Read-only containment flag — extracted server-side into ServiceContext.readOnly. */
    readOnly?: boolean;
  };
  provenance: AuthenticatedCaller[];
  message: RpcMessage;
}

export interface EnvelopeRpcTransport {
  /**
   * Deliver one envelope. Connectionless transports bind `signal` to the
   * physical request so cancellation cannot overtake admission on a second
   * connection. Ordered transports may ignore it and consume the subsequent
   * `request-cancel` envelope in channel order.
   */
  send(envelope: RpcEnvelope, signal?: AbortSignal): Promise<void>;
  onMessage(handler: (envelope: RpcEnvelope) => void): () => void;
  status?: () => RpcConnectionStatus;
  ready?: () => Promise<void>;
  onStatusChange?: (handler: (status: RpcConnectionStatus) => void) => () => void;
  /**
   * First-class streaming for transports that physically stream a response body
   * (HTTP). When present, `createRpcClient.stream()` delegates here instead of
   * the duplex `stream-request`/`stream-frame` envelope path. The core builds a
   * `stream-request` envelope; the transport POSTs it and returns the streaming
   * `Response`. Socket transports omit this and keep the frame-envelope path.
   *
   * `body` is the streaming REQUEST body. A capable transport carries it on
   * its native wire; incapable transports MUST throw rather than silently
   * dropping it or encoding it into args.
   */
  stream?(
    envelope: RpcEnvelope,
    signal?: AbortSignal | null,
    body?: ReadableStream<Uint8Array> | null,
    headTimeoutMs?: number,
    trafficClass?: RpcStreamTrafficClass
  ): Promise<Response>;
  /**
   * Streaming variant returning the decoded head + raw `ReadableStream<Uint8Array>`
   * body (no `Response` wrapper) — for RN clients. Transports that support duplex
   * streaming implement this; `createRpcClient.streamReadable()` delegates here.
   * `body` follows the same contract as `stream`.
   */
  streamReadable?(
    envelope: RpcEnvelope,
    signal?: AbortSignal | null,
    body?: ReadableStream<Uint8Array> | null,
    headTimeoutMs?: number,
    trafficClass?: RpcStreamTrafficClass
  ): Promise<DecodedFramedStream>;
  /**
   * UPLOAD-ONLY first-class hop for panel shell bridges (plan §1.6). A bridge
   * transport (Electron contextBridge / RN postMessage) cannot expose a full
   * `stream` — its downstream host session may be a plain loopback WS with no
   * response plane — but it CAN carry a streaming request body as explicit
   * bridge chunk messages (see `bridgeStream.ts`). The core calls this ONLY
   * when a request carries a `body` and the transport has no full `stream`
   * hook; body-less streams keep the duplex envelope path byte-identical.
   * Transports without it reject bodies loudly.
   */
  streamBody?(
    envelope: RpcEnvelope,
    signal?: AbortSignal | null,
    body?: ReadableStream<Uint8Array> | null
  ): Promise<Response>;
}

export type RpcConnectionStatus = "connected" | "connecting" | "disconnected";

export interface RpcRequestContext {
  caller: AuthenticatedCaller;
  origin: AuthenticatedCaller;
  method: string;
  args: unknown[];
  signal: AbortSignal;
  rpc: RpcClient;
}

export interface RpcEventContext {
  caller: AuthenticatedCaller;
  origin: AuthenticatedCaller;
  event: string;
  payload: unknown;
}

export type RpcContextHandler<TArgs extends unknown[] = unknown[], TReturn = unknown> = (
  request: RpcRequestContext & { args: TArgs }
) => TReturn | Promise<TReturn>;

export type RpcContextMethods = Record<string, RpcContextHandler<any, any>>;

export type RpcContextStreamingHandler = (
  request: RpcRequestContext,
  sink: (frame: StreamingMethodFrame) => Promise<void> | void
) => Promise<void>;

export type MethodMap = Record<string, (...args: any[]) => any>;
export type EventMap = Record<string, any>;

export type TypedCallProxy<TMethods extends MethodMap> = {
  [K in keyof TMethods & string]: (
    ...args: Parameters<TMethods[K]>
  ) => Promise<Awaited<ReturnType<TMethods[K]>>>;
};

export interface RpcPeer<
  TMethods extends MethodMap = MethodMap,
  TEvents extends EventMap = EventMap,
  TEmitEvents extends EventMap = TEvents,
> {
  readonly id: string;
  readonly destination?: RpcDestination;
  readonly call: TypedCallProxy<TMethods>;
  on<K extends keyof TEvents & string>(
    event: K,
    listener: (event: RpcEventContext & { payload: TEvents[K] }) => void,
    website: WebsiteMethodPolicy
  ): () => void;
  emit<K extends keyof TEmitEvents & string>(event: K, payload: TEmitEvents[K]): Promise<void>;
  withContract<C extends RpcContract, Role extends keyof C & string>(
    contract: C,
    role: Role
  ): RpcPeer<
    C[Role] extends { methods: infer M extends MethodMap } ? M : MethodMap,
    C[Role] extends { events: infer E extends EventMap } ? E : EventMap,
    C[Role] extends { emits: infer EE extends EventMap } ? EE : EventMap
  >;
}

export type RpcContract = Record<
  string,
  {
    methods?: MethodMap;
    events?: EventMap;
    emits?: EventMap;
  }
>;

export interface RpcClientConfig {
  selfId: string;
  /** Hosted duplex endpoints publish their dynamic contract on the same RPC carrier. */
  publishExposures?: boolean;
  /** Workspace identity attached to this client's caller attribution. */
  workspaceId?: string;
  transport: EnvelopeRpcTransport;
  /**
   * Lifetime owned by the client creator. Aborting it retires this RPC endpoint;
   * scoped clients and peers are borrowed views and cannot retire the owner.
   */
  lifetime?: AbortSignal;
  /** Cancellation of the currently executing invocation, captured per outbound
   * request. Cancels nested work without retiring a shared runtime endpoint. */
  invocationSignal?: () => AbortSignal | null | undefined;
  /**
   * Optional default deadline for the response HEAD and subsequent body-frame
   * silence. Omitted or `null` means unbounded; callers that own a bounded
   * operation may opt in explicitly.
   */
  streamIdleTimeoutMs?: number | null;
  callerKind?: CallerKind | "unknown";
  provenance?: AuthenticatedCaller[];
  /**
   * Installed runtimes opt in to the P3 authority-acquisition loop. On a
   * structured EACQUIRE response the client waits on authority.awaitDecision
   * without a deadline, then retries the exact original invocation.
   */
  authorityAcquisition?: "wait" | "return";
}

export interface RpcClient {
  readonly selfId: string;
  expose<TArgs extends unknown[], TReturn>(
    method: string,
    handler: RpcContextHandler<TArgs, TReturn>,
    website: WebsiteMethodPolicy
  ): void;
  exposeAll(
    methods: RpcContextMethods,
    website: Readonly<Record<string, WebsiteMethodPolicy>>
  ): void;
  exposeStreaming(
    method: string,
    handler: RpcContextStreamingHandler,
    website: WebsiteMethodPolicy
  ): void;
  call<T = unknown>(
    targetId: string,
    method: string,
    args: unknown[],
    options?: RpcCallOptions
  ): Promise<T>;
  stream(
    targetId: string,
    method: string,
    args: unknown[],
    options?: RpcStreamOptions
  ): Promise<Response>;
  /**
   * Like `stream`, but returns the decoded head + a raw `ReadableStream<Uint8Array>`
   * body instead of a `Response` — for React Native, whose whatwg-fetch `Response`
   * cannot consume a ReadableStream body (the caller reads it via `getReader()`).
   * Node callers should prefer `stream`.
   */
  streamReadable(
    targetId: string,
    method: string,
    args: unknown[],
    options?: RpcStreamOptions
  ): Promise<DecodedFramedStream>;
  emit(targetId: string, event: string, payload: unknown, options?: RpcCallOptions): Promise<void>;
  on(
    event: string,
    listener: (event: RpcEventContext) => void,
    website: WebsiteMethodPolicy
  ): () => void;
  peer<
    TMethods extends MethodMap = MethodMap,
    TEvents extends EventMap = EventMap,
    TEmitEvents extends EventMap = TEvents,
  >(
    targetId: string,
    options?: RpcTargetOptions
  ): RpcPeer<TMethods, TEvents, TEmitEvents>;
  status(): RpcConnectionStatus;
  ready(): Promise<void>;
  onStatusChange(handler: (status: RpcConnectionStatus) => void): () => void;
}

// =============================================================================
// IPC Envelope Types
// =============================================================================

/**
 * Message envelope for RPC over IPC.
 * Wraps RPC messages with source/target routing information.
 */
export interface ParentPortEnvelope {
  targetId: string;
  sourceId?: string;
  message: RpcMessage;
}

/**
 * Type guard for ParentPortEnvelope.
 */
export function isParentPortEnvelope(msg: unknown): msg is ParentPortEnvelope {
  if (typeof msg !== "object" || msg === null) return false;
  const envelope = msg as Record<string, unknown>;
  return (
    typeof envelope["targetId"] === "string" &&
    "message" in envelope &&
    typeof envelope["message"] === "object" &&
    envelope["message"] !== null
  );
}
